  --mountain-foreground: var(--mountain-50);
  --foreground-link: var(--fjord-550);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(1 0 0 / 15%);
  --ring: oklch(0.556 0 0);
  --ring-shadow: var(--gray-300);
  --backdrop: rgba(226, 232, 240, 0.2);

  /* Status tokens */
  --destructive: oklch(0.704 0.191 22.216);
  --destructive-hover: var(--red-700);
  --destructive-foreground: var(--red-300);
  --destructive-shadow: var(--red-300);
  --warning: var(--amber-800);
  --warning-hover: var(--amber-700);
  --warning-foreground: var(--amber-300);
  --success: var(--green-800);
  --success-hover: var(--green-700);
  --success-foreground: var(--green-300);
  --neutral: var(--blue-800);
  --neutral-hover: var(--blue-700);
  --neutral-foreground: var(--blue-300);
  --undefined: var(--mountain-800);
  --undefined-hover: var(--mountain-700);
  --undefined-foreground: var(--mountain-300);
  --disabled: var(--mountain-800);
  --disabled-foreground: var(--mountain-450);
  --hover: var(--mountain-800);

  /* Toggled tokens */
  --toggled: var(--gray-900);
  --toggled-foreground: var(--gray-200);
  --toggled-hover: var(--gray-800);

  /* Inverted tokens */
  --inverted: var(--mountain-900);
  --inverted-foreground: var(--mountain-50);
  --inverted-foreground-muted: var(--mountain-300);
  --inverted-destructive-foreground: var(--red-300);
  --inverted-success-foreground: var(--green-300);

  /* Decorative tokens */
  --decorative-background-mountain: var(--mountain-800);
  --decorative-background-fjord: var(--fjord-900);
  --decorative-background-nordic: var(--nordic-900);
  --decorative-background-aurora: var(--aurora-900);
  --decorative-background-dusk: var(--dusk-900);
  --decorative-background-orange: var(--orange-900);
  --decorative-background-sky: var(--sky-900);
  --decorative-background-gray: var(--gray-900);

  /* Decorative background hover tokens */
  --decorative-background-hover-mountain: var(--mountain-900);
  --decorative-background-hover-fjord: var(--fjord-900);
  --decorative-background-hover-nordic: var(--nordic-900);
  --decorative-background-hover-aurora: var(--aurora-900);
  --decorative-background-hover-dusk: var(--dusk-900);
  --decorative-background-hover-orange: var(--orange-900);
  --decorative-background-hover-sky: var(--sky-900);

  /* Decorative foreground tokens */
  --decorative-foreground-mountain: var(--mountain-300);
  --decorative-foreground-fjord: var(--fjord-300);
  --decorative-foreground-nordic: var(--nordic-300);
  --decorative-foreground-aurora: var(--aurora-300);
  --decorative-foreground-dusk: var(--dusk-400);
  --decorative-foreground-orange: var(--orange-300);
  --decorative-foreground-sky: var(--sky-300);
  --decorative-foreground-gray: var(--gray-300);

  /* Gradient tokens */
  --gradient-nordic: linear-gradient(
    -100deg,
    var(--nordic-900) 0%,
    var(--nordic-600) 44%,
    var(--nordic-800) 100%
  );
  --gradient-aurora: linear-gradient(
    -100deg,
    var(--aurora-900) 0%,
    var(--aurora-600) 50%,
    var(--aurora-800) 100%
  );
  --gradient-dusk: linear-gradient(
    -100deg,
    var(--dusk-900) 0%,
    var(--dusk-600) 48%,
    var(--dusk-800) 100%
  );
  --gradient-equinox: linear-gradient(
    -100deg,
    var(--dusk-400) 0%,
    var(--dusk-700) 40%,
    var(--aurora-950) 60%,
    var(--aurora-900) 100%
  );
  --gradient-summer: linear-gradient(
    -100deg,
    var(--nordic-900) 0%,
    var(--dusk-950) 50%,
    var(--aurora-900) 100%
  );
  --gradient-spring: linear-gradient(
    -100deg,
    var(--aurora-950) 0%,
    var(--nordic-900) 50%,
    var(--aurora-900) 100%
  );
  --gradient-fall: linear-gradient(
    -100deg,
    var(--fjord-450) 0%,
    var(--dusk-450) 50%,
    var(--dusk-700) 100%
  );

  /* Sidebar */
  --sidebar: oklch(0.205 0 0);
  --sidebar-foreground: oklch(0.985 0 0);
  --sidebar-primary: oklch(0.488 0.243 264.376);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.269 0 0);
  --sidebar-accent-foreground: oklch(0.985 0 0);
  --sidebar-border: oklch(1 0 0 / 10%);
  --sidebar-ring: oklch(0.556 0 0);
  --chart-1: oklch(0.488 0.243 264.376);
  --chart-2: oklch(0.696 0.17 162.48);
  --chart-3: oklch(0.769 0.188 70.08);
  --chart-4: oklch(0.627 0.265 303.9);
  --chart-5: oklch(0.645 0.246 16.439);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
}

@layer utilities {
  [data-state="closed"] {
    --tw-animation-fill-mode: forwards;
  }

  @keyframes accordion-down {
    from {
      height: 0;
    }
    to {
      height: var(--radix-accordion-content-height);
    }
  }

  @keyframes accordion-up {
    from {
      height: var(--radix-accordion-content-height);
    }
    to {
      height: 0;
    }
  }

  .animate-accordion-down {
    animation: accordion-down 0.2s ease-out;
  }

  .animate-accordion-up {
    animation: accordion-up 0.2s ease-out;
  }
}
